def prepare_photo(raw):
    if len(raw) > 10 * 1024 * 1024:
        raise ValueError('사진은 10MB 이하로 올려 주세요.')
    try:
        with Image.open(io.BytesIO(raw)) as source:
            if source.format not in ['JPEG', 'PNG', 'WEBP'] or source.width * source.height > 25000000:
                raise ValueError('JPG, PNG, WEBP 사진을 사용해 주세요. 최대 2,500만 화소입니다.')
            image = ImageOps.exif_transpose(source).convert('RGB')
            image.thumbnail((1280, 1280))
            output = io.BytesIO()
            image.save(output, format='JPEG', quality=78, optimize=True)
            return base64.b64encode(output.getvalue()).decode('ascii')
    except (OSError, Image.DecompressionBombError) as exc:
        raise ValueError('사진을 열 수 없습니다. 다른 JPG·PNG 사진을 선택해 주세요.') from exc


def transition_quest(q, action, actor):
    if action == '사진으로 미션 완료':
        if actor != q['담당'] or q['상태'] != '진행 중' or not q.get('사진'):
            raise ValueError('담당자가 완료 사진을 먼저 올려 주세요.')
        q['상태'] = '지급 대기'
        q['완료일'] = str(today_kst())
    elif action == '지급 완료':
        if actor != q['등록자'] or q['상태'] != '지급 대기':
            raise ValueError('미션을 등록한 가족만 지급 완료를 기록할 수 있습니다.')
        q['상태'] = '지급 완료'
        q['지급일'] = str(today_kst())
    else:
        raise ValueError('허용되지 않은 작업입니다.')


def quest_summary(d):
    return [{'구성원': m['이름'],
             '배정 미션(개)': sum(q['담당']==m['id'] for q in d['quests']),
             '완료 미션(개)': sum(q['담당']==m['id'] and q['상태'] in ['지급 대기','지급 완료'] for q in d['quests']),
             '받을 미션금(원)': sum(q['용돈'] for q in d['quests'] if q['담당']==m['id'] and q['상태']=='지급 대기'),
             '받은 미션금(원)': sum(q['용돈'] for q in d['quests'] if q['담당']==m['id'] and q['상태']=='지급 완료')}
            for m in d['members']]


COINS_PER_MISSION = 10
REWARD_DEFAULTS = [dict(id=f'allowance_{amount}', name=f'용돈 {amount:,}원', cost=amount//50)
                   for amount in range(1000, 5001, 1000)]


def reward_products(d):
    custom = d.get('rewards', [])
    default_ids = {r['id'] for r in REWARD_DEFAULTS}
    return [*REWARD_DEFAULTS, *(r for r in custom if r['id'] not in default_ids)]


def daily_reward_products(d, family_key, day):
    from random import Random
    featured = Random(f'{family_key}:{day}').sample(REWARD_DEFAULTS, 3)
    default_ids = {r['id'] for r in REWARD_DEFAULTS}
    return [*sorted(featured, key=lambda r: r['cost']),
            *(r for r in reward_products(d) if r['id'] not in default_ids)]


def member_rewards(d, member):
    return [r for r in reversed(d.get('coin_spends', [])) if r.get('member') == member]


COMPLETED = ('지급 대기','지급 완료')


def now_kst():
    return datetime.now(ZoneInfo('Asia/Seoul')).isoformat(timespec='seconds')


def coin_state(d):
    credits = {}
    for q in d['quests']:
        if q['상태'] in COMPLETED:
            credits.setdefault(q['id'],dict(id=q['id'],name=q['제목'],member=q['담당'],
                coins=q.get('코인',COINS_PER_MISSION),at=q.get('완료시각') or q.get('완료일') or ''))
    spends = d.get('coin_spends',[])
    earned = sum(r['coins'] for r in credits.values())
    return earned, earned-sum(r['coins'] for r in spends), sorted(credits.values(),key=lambda r:r['at'],reverse=True)


def buy_reward(d, reward_id, operation, member):
    if member not in names(d):
        raise ValueError('보상을 받을 가족을 선택해 주세요.')
    entries=d.setdefault('coin_spends',[])
    if any(r['id']==operation for r in entries):
        return False
    product=next((r for r in reward_products(d) if r['id']==reward_id),None)
    if not product:
        raise ValueError('선택한 보상을 찾을 수 없어요.')
    balance=coin_state(d)[1]
    if balance<product['cost']:
        raise ValueError(f"코인이 {product['cost']-balance:,}개 부족해요.")
    entries.append(dict(id=operation,name=product['name'],coins=product['cost'],at=now_kst(),member=member))
    return True


def level_info(d):
    count=sum(bool(group_completion(g)) for g in group_missions(d['quests'])); return 1+count//5, count, 5-count%5


def celebration_audio():
    import wave, struct
    stream=io.BytesIO()
    with wave.open(stream,'wb') as f:
        f.setparams((1,2,16000,0,'NONE','not compressed'))
        frames=[]
        for hz in (523.25,659.25,783.99):
            for i in range(2400):
                envelope=min(i/180,1)*max(0,1-i/2400)
                frames.append(struct.pack('<h',int(2200*envelope*math.sin(2*math.pi*hz*i/16000))))
        f.writeframes(b''.join(frames))
    return stream.getvalue()


def celebrate(d):
    event=st.session_state.pop('coin_celebration',None)
