def shop_admin(d):
    expected=os.environ.get('BALANCE_ADMIN_PIN','')
    if not expected:
        st.caption('배포 설정에 관리자 비밀번호(BALANCE_ADMIN_PIN)를 지정하면 상품을 관리할 수 있어요.');return
    pin=st.text_input('관리자 비밀번호',type='password',key='shop_admin_pin')
    if not secrets.compare_digest(pin.encode(),expected.encode()): return
    products=[r for r in reward_products(d) if r['id'] not in {x['id'] for x in REWARD_DEFAULTS}]
    choice=draft('large_choice','shop_product','상품 선택',['새 상품']+[r['id'] for r in products],format_func=lambda x: next((r['name'] for r in products if r['id']==x),x))
    old=next((r for r in products if r['id']==choice),None)
    label=draft('text_input','shop_name_'+choice,'보상 이름',value=old['name'] if old else '',max_chars=60)
    cost=draft('number_input','shop_cost_'+choice,'필요한 코인',1,100000,old['cost'] if old else 30)
    if st.button('상품 저장'):
        if not label.strip(): st.error('보상 이름을 적어 주세요.')
        else:
            d['rewards']=[r for r in products if r['id']!=choice]+[dict(id=choice if old else uid(),name=label.strip(),cost=int(cost))]
            saved_rerun()


def growth(d):
    level,count,left=level_info(d)
    st.header('🏡 가족 성장')
    st.markdown(f'<div class="home-intro"><h2>{"🏠" if level==1 else "🏡 ✨" if level<4 else "🌿 🏡 🌟"} 가족 레벨 {level}</h2><p>함께 완료한 미션 {count}개</p></div>',unsafe_allow_html=True)
    st.progress((count%5)/5,text=f'다음 레벨까지 미션 {left}개')
    st.write('오늘도 함께해서 더 행복한 우리 가족!')


def group_missions(quests):
    groups = {}
    for q in quests:
        # 그룹 ID가 없는 기록은 제목만으로 같은 미션이라고 판단하지 않습니다.
        key = ('group', q['그룹']) if q.get('그룹') else ('legacy', q['id'])
        groups.setdefault(key, []).append(q)
    return list(groups.values())


def mission_photo_controls(d, group, q, n, source):
    selected = q['담당']
    photo_key = 'mission_photo_'+q['id']
    upload_key = 'photo_'+source+'_'+q['id']
    error_key = 'photo_error_'+q['id']
    def keep_photo(upload_key=upload_key, photo_key=photo_key, error_key=error_key):
        st.session_state.pop(error_key, None)
        st.session_state.drafts.pop(photo_key, None)
        photo = st.session_state.get(upload_key)
        if photo is None:
            st.session_state.drafts.pop(photo_key,None)
            return
        try:
            encoded = prepare_photo(photo.getvalue())
            st.session_state.drafts[photo_key] = encoded
        except ValueError as exc:
            st.session_state[error_key] = str(exc)
    st.file_uploader('완료 사진 선택하기', type=['jpg','jpeg','png','webp'], key=upload_key, on_change=keep_photo)
    if st.session_state.get(error_key):
        st.error(st.session_state[error_key])
    encoded = st.session_state.drafts.get(photo_key)
    if encoded:
        st.caption('완료 사진이 임시 저장됐어요.')
        if st.button('임시 사진 지우기',key='drop_'+source+'_'+q['id']):
            st.session_state.drafts.pop(photo_key,None)
            saved_rerun()
    if st.button('📷 사진 제출하고 미션 완료!', key='finish_'+source+'_'+q['id'], disabled=not encoded, use_container_width=True):
        try:
            if group_completion(group):
                raise ValueError('이미 다른 가족이 완료한 미션이에요.')
            if sum(len(x.get('사진') or '') for x in d['quests'])+len(encoded)>15*1024*1024:
                raise ValueError('사진 보관 한도에 도달했습니다.')
            old_level = level_info(d)[0]
            updated = dict(q, 사진=encoded)
            transition_quest(updated, '사진으로 미션 완료', selected)
            q.update(updated)
            q['완료시각'] = now_kst()
            q.setdefault('코인', COINS_PER_MISSION)
            new_level = level_info(d)[0]
            st.session_state.coin_celebration = (q['코인'],new_level if new_level > old_level else None)
            st.session_state.drafts.pop(photo_key,None)
            st.session_state.reward_family = selected
            st.session_state.active_actor = selected
            st.session_state.quest_actor_reset = True
            st.session_state.mission_filter = '완료한 미션'
            st.session_state.quest_focus = q['id']
            for dk in list(st.session_state.drafts):
                if dk.endswith(('_reward_family', '_quest_actor')):
                    st.session_state.drafts.pop(dk)
                    st.session_state.pop('draft_widget_'+dk,None)
            st.session_state.quest_notice = f"{n[selected]}님 미션 성공! +{q['코인']:,}코인 적립 🎉"
            saved_rerun()
        except ValueError as exc:
            st.error(str(exc))


def quests(d):
    st.header('🎯 집안일 퀘스트')
    celebrate(d)
    notice = st.session_state.pop('quest_notice', None)
    if notice:
        st.success(notice)
        st.toast(notice, icon='🎉')
    if not require_family(d):
        return
    n = names(d)
    steps = ['① 미션 만들기', '② 미션 완료하기', '③ 미션금 보기']
    default_step = steps[1] if d['quests'] else steps[0]
    step = st.session_state.get('quest_step', default_step)
    with st.container(key='quest_steps'):
        for option in steps:
            st.button(option, key='quest_step_'+option, type='primary' if option == step else 'secondary',
                      on_click=st.session_state.update, args=({'quest_step': option},), use_container_width=True)
    actor = st.session_state.get('active_actor')
    if actor not in n:
        actor = next(iter(n))
    if st.session_state.pop('quest_actor_reset', False):
        st.session_state.pop('draft_widget_'+st.session_state.family_key[:12]+'_quests_532_quest_actor', None)
    if step != steps[2]:
        actor = draft('large_choice', 'quests_532', '등록하는 가족' if step == steps[0] else '누구의 미션을 볼까요?',
                             list(n), format_func=n.get, index=list(n).index(actor), key='quest_actor')
        st.session_state.active_actor = actor
    if step == steps[0]:
        st.write('할 일, 맡을 가족, 미션금을 정해 주세요.')
        with st.container(border=True):
            title = draft('text_input', 'quests_537', '어떤 미션인가요?', max_chars=60, placeholder='예: 설거지하기')
            detail = ''
            eligible = [member_id for member_id in n if member_id != actor]
            chosen = draft('visible_checks', 'quest_assignees_'+actor, '누가 할까요?', eligible, format_func=n.get) if eligible else []
            people = [member_id for member_id in chosen if member_id in eligible]
            if not eligible:
                st.write('미션을 맡길 다른 가족을 가족 설정에서 먼저 추가해 주세요.')
            reward = draft('number_input','unified_mission_reward','한 사람에게 줄 미션금 (코인)',0,1000000,COINS_PER_MISSION,step=1,help='완료 사진을 제출하면 바로 적립돼요.')
            consent = st.checkbox('안전과 미션금을 가족과 합의했습니다.')
            if st.button('미션 등록하기', use_container_width=True, disabled=not eligible):
                if not title.strip() or not people or not consent:
                    
                    if not title.strip(): st.error('할 일: 미션 이름을 적어 주세요.')
                    if not people: st.error('담당자: 맡을 가족을 한 명 이상 골라 주세요.')
                    if not consent: st.error('가족과 정한 안전·미션금을 확인해 주세요.')
                else:
                    group_id = uid()
                    for person in people:
                        d['quests'].append({'id': uid(), '그룹': group_id, '제목': title.strip(), '설명': detail,
                                            '담당': person, '등록자': actor, '용돈': reward, '코인': int(reward),
                                            '상태': '진행 중', '사진': None, '완료일': None, '지급일': None})
                    st.session_state.quest_step = steps[1]
                    st.session_state.quest_notice = '미션을 등록했어요! 담당 가족은 할 일을 마친 뒤 사진을 올리세요.'
                    saved_rerun()
    elif step == steps[1]:
        groups = group_missions(d['quests'])
        focus = st.session_state.get('quest_focus')
        pending, done = personal_missions(groups, actor)
        current = st.session_state.get('mission_filter', '진행 중')
        left, right = st.columns(2)
        for col, label, items in [(left, '진행 중', pending), (right, '완료한 미션', done)]:
            with col:
                st.button(f'{label} {len(items)}개', key='mission_filter_'+label,
                          type='primary' if current == label else 'secondary', use_container_width=True,
                          on_click=st.session_state.update, args=({'mission_filter': label},))
        shown = done if current == '완료한 미션' else pending[::-1]
        if not shown:
            st.caption(f'{n[actor]}님이 완료한 미션이 없어요.' if current == '완료한 미션' else f'{n[actor]}님이 맡은 진행 중 미션이 없어요.')
        for group, q in sorted(shown, key=lambda pair: pair[1]['id'] != focus):
            selected = q['담당']
            card_done = bool(group_completion(group))
            icon = '✓' if card_done else '🎯'
            coins = q.get('코인', COINS_PER_MISSION)
            with st.expander(f"{icon} {q['제목']} · {coins:,}코인 " + (" · 완료" if card_done else " · 사진 제출"), expanded=q['id'] == focus):
                st.caption('등록: '+ n.get(q['등록자'], '알 수 없음') + ' / 담당: ' + ' · '.join(
                    ('✓ ' if item['상태'] in COMPLETED else '') + n.get(item['담당'], '알 수 없음') for item in group))
                if q.get('설명'):
                    st.write(q['설명'])
                if card_done and q.get('사진') and st.toggle('완료 사진 보기', key='view_photo_'+q['id']):
                    st.image(base64.b64decode(q['사진']), caption=n[selected]+'의 완료 사진', width=320)
                if not card_done and q['상태']=='진행 중':
                    mission_photo_controls(d, group, q, n, 'assigned')
        # Completed registered missions already appear in the completed list.
        registered = [g for g in groups if g[0]['등록자'] == actor and not group_completion(g)] if current == '진행 중' else []
        if registered:
            with st.expander(f'내가 등록한 진행 중 미션 {len(registered)}개'):
                for group in reversed(registered):
                    st.write(group[0]['제목'])
                    for item in group:
                        if item['상태'] == '진행 중' and item['담당'] in n:
                            if st.toggle(f"📷 {n[item['담당']]}님 사진 올리기", key='registered_submit_'+item['id']):
                                mission_photo_controls(d, group, item, n, 'registered')
    else:
        reward_who = draft('large_choice', 'quests_614', '미션금 확인할 가족', list(n), format_func=n.get, index=list(n).index(st.session_state.get('reward_family') if st.session_state.get('reward_family') in n else actor), key='reward_family')
        earned = sum(r['coins'] for r in coin_state(d)[2] if r['member']==reward_who)
        st.metric(n[reward_who]+'님의 누적 미션금', f'{earned:,}코인')
        if d['quests']:
            st.subheader('가족별 미션 현황')
            rows = quest_summary(d)
            bars = [{'가족':row['구성원'], '미션 수':int(row['완료 미션(개)'])} for row in rows]
            fig = px.bar(pd.DataFrame(bars), x='미션 수', y='가족',
                         orientation='h', text='미션 수',
                         color_discrete_sequence=['#21854B'],
                         category_orders={'가족':[r['구성원'] for r in rows]})
            fig.update_traces(width=0.30, texttemplate='%{text}', textposition='inside',
                              insidetextanchor='middle', textfont_size=18, textangle=0,
                              hovertemplate='%{y}: %{x}개<extra>%{fullData.name}</extra>')
            # Hide zero-value labels without hiding families with no assigned missions.
            for trace in fig.data:
                trace.text = [str(int(value)) if value else '' for value in trace.x]
            largest = max((int(r['완료 미션(개)']) for r in rows), default=0)
            fig.update_layout(height=max(260, 65*len(rows)+90),
                              margin=dict(l=0,r=16,t=10,b=10),
                              font=dict(size=18), plot_bgcolor='#FDFDFF', paper_bgcolor='#FDFDFF',
                              legend=dict(title=None,orientation='h',y=1.12,x=0),
                              xaxis_title=None,yaxis_title=None, bargap=0.7,
                              uniformtext_minsize=16,uniformtext_mode='hide')
            fig.update_xaxes(rangemode='tozero', range=[0,max(1,largest)*1.08],
                             dtick=max(1,math.ceil(largest/5)), showgrid=True,gridcolor='#EEF0F4',zeroline=False)
            fig.update_yaxes(showgrid=False, ticks='')
            st.plotly_chart(fig, use_container_width=True, config={'displayModeBar':False,'staticPlot':True})
            st.caption('완료한 미션만 표시해요. 미완료 미션은 그래프에 포함하지 않아요.')
            active = [row for row in quest_summary(d) if row['배정 미션(개)']]
            if len(active)>1:
                most = max(active, key=lambda row:row['배정 미션(개)'])
                least = min(active, key=lambda row:row['배정 미션(개)'])
                if most['배정 미션(개)']-least['배정 미션(개)']>=2:
                    st.write(f"{most['구성원']}에게 미션이 더 많이 배정되어 있어요. 다음 미션은 {least['구성원']}에게 부탁해 보세요.")
        else:
            st.write('미션을 등록하면 분담과 미션금 분석이 나타나요.')


def meals(d):
    st.header('🍚 함께 식사')
    if not require_family(d):
        return
    n = names(d)
    goal = int(d['meal_goal'])
    tab1, tab2 = st.tabs(['가능 시간 찾기', '식사 기록·분석'])
    with tab1:
        st.subheader('한 번에 식사 시간 정하기')
        with st.container(border=True):
            people = draft('pills', 'meals_665', '참여할 가족', list(n), format_func=n.get,
                              selection_mode='multi', default=list(n)) or []
            day_name = draft('pills', 'meals_667', '요일 하나 선택', DAYS, selection_mode='single', default='화')
            slots = draft('pills', 'meals_668', '그날 가능한 끼니', SLOTS, selection_mode='multi', default=[]) or []
            if st.button('이 일정 추가',use_container_width=True):
                if not people or day_name not in DAYS or not slots:
                    st.error('가족·요일·끼니를 선택해 주세요.')
                else:
                    existing = {(r['구성원'],r['요일'],r['끼니']) for r in d['availability']}
                    added = 0
                    for person in people:
                        for meal in slots:
                            item = (person,day_name,meal)
                            if item not in existing:
                                d['availability'].append({'구성원':person,'요일':day_name,'끼니':meal})
                                existing.add(item)
                                added += 1
                    st.session_state['meal_schedule_notice'] = '일정을 추가했어요.' if added else '이미 등록된 일정이에요.'
                    saved_rerun()
        notice = st.session_state.pop('meal_schedule_notice',None)
        if notice:
            st.success(notice)
        result = meal_candidates(d)
        if result:
            st.subheader('함께 먹기 좋은 시간 TOP 3')
            for candidate in result[:3]:
                with st.container(border=True):
                    st.write(f"**{candidate['요일']}요일 {candidate['끼니']} · {candidate['가능 인원']}명**")
                    st.write(' · '.join(n[i] for i in candidate['참여']))
            st.write('이 중 한 끼부터 함께 먹어 보세요.')
        else:
            st.write('가족 두 명 이상이 가능한 끼니를 등록하면 함께 먹기 좋은 시간을 추천해요.')
    with tab2:
        with st.container(border=True):
            day = draft('date_input', 'meals_699', '식사한 날짜', value=today_kst(), max_value=today_kst(), key='meal_date_'+today_kst().isoformat())
            slot = draft('large_choice', 'meals_700', '함께한 끼니', SLOTS)
            people = draft('visible_checks', 'meals_701', '참여한 가족', list(n), format_func=n.get)
            if st.button('식사 기록 저장'):
                if len(people) < 2:
                    st.error('가족 2명 이상을 선택해 주세요.')
                elif any(r['날짜'] == str(day) and r['끼니'] == slot for r in d['meals']):
                    st.error('이미 기록된 끼니입니다. 아래 기록을 삭제하고 다시 입력하세요.')
                else:
                    d['meals'].append({'id': uid(), '날짜': str(day), '끼니': slot, '참여': people})
                    saved_rerun()
        records = weekly_meals(d)
        st.metric('이번 주 함께한 식사', f'{len(records)}회', f'목표까지 {max(0, goal-len(records))}회 남음', delta_color='off')
        st.progress(min(1.0, len(records)/goal))
        start = today_kst() - timedelta(days=today_kst().weekday())
        frame = pd.DataFrame([{'요일': DAYS[i], '함께한 식사(회)': sum(r['날짜'] == str(start+timedelta(days=i)) for r in records)}
                              for i in range(7)])
        fig = px.bar(frame, x='요일', y='함께한 식사(회)',
                     category_orders={'요일': DAYS}, color_discrete_sequence=['#21854B'])
        fig.update_traces(width=0.38, text=[str(v) if v else '' for v in frame['함께한 식사(회)']],
                          textposition='outside', cliponaxis=False,
                          hovertemplate='%{x}요일 · %{y}회<extra></extra>')
        fig.update_layout(height=280, margin=dict(l=8,r=8,t=25,b=10),
                          paper_bgcolor='#FFFFFF', plot_bgcolor='#FFFFFF',
                          font=dict(size=18), showlegend=False,
                          xaxis=dict(title=None, fixedrange=True),
                          yaxis=dict(title=None, range=[0,max(3,int(frame['함께한 식사(회)'].max()))+0.6],
                                     dtick=1, fixedrange=True, gridcolor='#E8EEE9', zeroline=False))
        st.plotly_chart(fig, use_container_width=True, config={'displayModeBar':False})
        for member in d['members']:
            count = sum(member['id'] in r['참여'] for r in records)
            st.write(f"• {member['이름']}: 이번 주 {count}회 참여")
        if d['meals']:
            st.dataframe(pd.DataFrame([{'날짜': r['날짜'], '끼니': r['끼니'], '가족': ', '.join(n[i] for i in r['참여'])}
                                        for r in sorted(d['meals'], key=lambda r: r['날짜'], reverse=True)]), hide_index=True)
        delete_record(d, 'meals', lambda r: f"{r['날짜']} {r['끼니']}", 'del_meal')


